INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('86e513e7-d0a7-4419-8edd-6113629d7998','e9ebefcd-c496-45e8-b816-a79f8442ba85',$$A longtime community organizer, de la Torre supports police accountability and transparency — body cameras on officers and cameras in cars — crediting such reforms for moving the police from violent toward more professional conduct.$$,ARRAY['https://patch.com/california/santamonica/thats-oscar-de-la-torre-not-oscar-de-la-hoya']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
