INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('86e513e7-d0a7-4419-8edd-6113629d7998','d1792200-1d3b-4955-a0b7-0e6980d7a7b2',$$De la Torre's family was central to the California Voting Rights Act case seeking to replace Santa Monica's citywide elections with district voting to empower the Latino Pico neighborhood, a voting-rights expansion position.$$,ARRAY['https://smmirror.com/2021/01/city-council-to-decide-whether-member-can-participate-in-voting-rights-case-against-santa-monica/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
